     6	/** A period of the year in which nights are high-season nights. */
     7	@FunctionalInterface
     8	interface Season {
     9	
    10	    boolean includes(LocalDate night);
    11	
    12	    /** A period that repeats every year, from {@code start} to {@code end} inclusive; it may cross New Year. */
    13	    static Season everyYear(MonthDay start, MonthDay end) {
    14	        return night -> {
    15	            MonthDay day = MonthDay.from(night);
    16	            return start.isAfter(end)
    17	                    ? !day.isBefore(start) || !day.isAfter(end)
    18	                    : !day.isBefore(start) && !day.isAfter(end);
    19	        };
    20	    }
    21	
    22	    /** A single period, from {@code first} to {@code last} inclusive. */
    23	    static Season between(LocalDate first, LocalDate last) {
    24	        return night -> !night.isBefore(first) && !night.isAfter(last);
    25	    }
    26	}
